let additions = [
    #("connect-src 'self' https://www.google.com https://mpc2-prod-23-is5qnl632q-ue.a.run.app", "mpc2-prod-23-is5qnl632q-ue.a.run.app"),
    #("img-src 'self' data: https://www.google.com https://www.facebook.com https://www.google.ie https://www.google.com.gh", "www.google.ie"),
    #("img-src 'self' data: https://www.google.com https://www.facebook.com https://www.google.ie https://www.google.com.gh", "www.google.com.gh"),
    #("style-src 'self' 'unsafe-inline' https://www.gstatic.com", "www.gstatic.com"),
    #("frame-src 'self' https://www.facebook.com https://toolytics.pa.clients6.google.com", "toolytics.pa.clients6.google.com"),
  ]
  let policy = csp.policy("ABC123")
  let bare_policy = csp.policy("")
  [policy, bare_policy]
  |> list.each(fn(p) {
    list.each(additions, fn(pair) {
      let #(directive, domain) = pair
      p |> string.contains(directive) |> should.be_true
      p |> string.split(domain) |> list.length |> should.equal(2)
    })
    p |> string.ends_with(";") |> should.be_false
    p |> string.contains(";;") |> should.be_false
    p |> string.contains("'unsafe-eval'") |> should.be_false
    p |> string.contains("*") |> should.be_false
  })
